6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   static const String _baseCurrency = 'USD';
15: 
16:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
17: 
18:   late final AnimationController _fadeController;
19: 
20:   late Future<List<CurrencyModel>> _currencyListFuture;
21: 
22:   final FocusNode _focusNode = FocusNode();
23: 
24:   List<CurrencyModel> _allCurrencies = [];
25: 
26:   int _currentPage = 0;
27: 
28:   bool _hasMore = false;
29: 
30:   @override
31:   void initState() {
32:     super.initState();
33:     _initAnimation();
34:     _initData();
35:   }
36: 
37:   @override
38:   void dispose() {
39:     _focusNode.dispose();
40:     _filteredCurrenciesNotifier.dispose();
41:     _fadeController.dispose();
42:     super.dispose();
43:   }
44: 
45:   void _initAnimation() {
46:     _fadeController = AnimationController(
47:       duration: Duration(milliseconds: 400),
48:       vsync: this,
49:     );
50:   }
51: 
52:   void _initData() {
53:     final currencyRepository = context.read<CurrencyRepository>();
54: 
55:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: _baseCurrency)).then((CurrencyPage page) {
56:       _applyPage(page);
57: 
58:       _fadeController.forward(); // запускаем анимацию
59: 
60:       currencyRepository.saveCurrencyList(page.items);
61: 
62:       return page.items;
63:     });
64:   }
65: 
66:   /// Применяет загруженную страницу: первая страница заменяет список,
67:   /// последующие — дополняют его.
68:   void _applyPage(CurrencyPage page, {bool append = false}) {
69:     final List<CurrencyModel> value = append ? <CurrencyModel>[..._allCurrencies, ...page.items] : page.items;
70: 
71:     _allCurrencies = value;
72:     _currentPage = page.page;
73:     _hasMore = page.hasMore;
74: 
75:     if (mounted) {
76:       setState(() {});
77:     }
78:   }
79: 
80:   /// Кнопка «Показать ещё» видна, только пока есть следующая страница.
81:   Future<void> _loadMore() async {
82:     if (!_hasMore) return;
83: 
84:     final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
85:     final CurrencyPage page = await currencyRepository.fetchRates(
86:       CurrencyPageRequest(base: _baseCurrency, page: _currentPage + 1),
87:     );
88: 
89:     currencyRepository.saveCurrencyList(page.items);
90: 
91:     _applyPage(page, append: true);
92:     _filteredCurrenciesNotifier.value = _allCurrencies;
93:   }
94: 
95:   /// При потере фокуса экраном список обновляется свежим запросом с base: 'USD'.
96:   void _onFocusChanged() {
97:     if (_focusNode.hasFocus) return;
98: 
99:     _reload();
100:   }
101: 
102:   Future<void> _reload() async {
103:     final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
104:     final CurrencyPage page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: _baseCurrency));
105: 
106:     currencyRepository.saveCurrencyList(page.items);
107: 
108:     _applyPage(page);
109:     _filteredCurrenciesNotifier.value = _allCurrencies;
110:   }
111: 
112:   void _filterCurrencies(String query) {
113:     final String lowerQuery = query.toLowerCase();
114:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
115:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
116:     });
117: 
118:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
119:   }
120: 
121:   @override
122:   Widget build(BuildContext context) {
123:     return Focus(
124:       focusNode: _focusNode,
125:       onFocusChange: (_) => _onFocusChanged(),
126:       child: Scaffold(
127:         appBar: AppBar(title: Text(context.loc.currencyRate)),
128:         body: FutureBuilder(
129:           future: _currencyListFuture,
130:           builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
131:             final List<CurrencyModel>? data = snapshot.data;
132:             if (data == null) return const SizedBox.shrink();
133: 
134:             return FadeTransition(
135:               opacity: _fadeController.view,
136:               child: Column(
137:                 children: [
138:                   Padding(
139:                     padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
140:                     child: SearchView(onChanged: _filterCurrencies),
141:                   ),
142:                   Expanded(
143:                     child: ValueListenableBuilder<List<CurrencyModel>>(
144:                       valueListenable: _filteredCurrenciesNotifier,
145:                       builder: (BuildContext context, List<CurrencyModel> data, _) {
146:                         return ListView.builder(
147:                           itemCount: data.length,
148:                           itemBuilder: (BuildContext context, int index) {
149:                             final CurrencyModel currency = data[index];
150: 
151:                             return Padding(
152:                               key: ValueKey(currency.id),
153:                               padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
154:                               child: CurrencyCard(model: currency),
155:                             );
156:                           },
157:                           padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
158:                         );
159:                       },
160:                     ),
161:                   ),

